"""Symbolic harness layout, declaration ordering, and inverse reading.

The layout walker follows the toolkit's MainBuilder numbering convention:
inputs in parameter order then the non-void result; each visited bool, char,
int, enum, string buffer, array, or struct reserves one increasing xN.  A
scalar has one object; a composite reserves its own ID but no object, then its
children reserve IDs recursively.  Aliases reserve no ID and add no path
component.  The inverse reader consumes exactly those IDs and recovers typed
values, applying string NUL recovery and leaf range checks.
"""

from .wire import WireError


def int_width(bits):
    """Smallest of 1, 2, 4, 8 bytes holding the given bit count."""
    if bits <= 8:
        return 1
    if bits <= 16:
        return 2
    if bits <= 32:
        return 4
    return 8


def type_order(types, modules):
    """Declaration names in dependency-before-user postorder.

    Walks params in order then the result for each module in module order;
    struct fields in order and array/alias children first.  Enum, struct and
    alias declarations appear once; primitives, strings and arrays are not
    declarations.  ``modules`` items have ``params`` and ``result`` keys.
    """
    seen = set()
    order = []

    def emit(name):
        if name not in seen:
            seen.add(name)
            order.append(name)

    def visit(tname):
        d = types.defs[tname]
        kind = d.kind
        if kind == 'alias':
            visit(d.target)
            emit(tname)
        elif kind == 'struct':
            for (_, ft) in d.fields:
                visit(ft)
            emit(tname)
        elif kind == 'array':
            visit(d.element)
        elif kind == 'enum':
            emit(tname)

    for m in modules:
        for (_, tname) in m['params']:
            visit(tname)
        visit(m['result'][1])
    return order


def layout(types, params, result):
    """Number the entry harness.

    Returns (slots, id_count) where slots are (id, path, width) triples for
    scalar objects in harness order and id_count is the total reserved IDs.
    ``params`` is a list of (name, type_name); ``result`` is (name, type_name)
    or None when the result is void.
    """
    counter = [0]
    slots = []

    def visit(tname, path):
        d = types.defs[tname]
        kind = d.kind
        if kind == 'alias':
            visit(d.target, path)
        elif kind == 'bool' or kind == 'char':
            slots.append((counter[0], path, 1))
            counter[0] += 1
        elif kind == 'int':
            slots.append((counter[0], path, int_width(d.bits)))
            counter[0] += 1
        elif kind == 'enum':
            slots.append((counter[0], path, 4))
            counter[0] += 1
        elif kind == 'string':
            counter[0] += 1  # buffer ID: composite, no object
            for i in range(d.maxsize):
                slots.append((counter[0], path + [i], 1))
                counter[0] += 1
        elif kind == 'array':
            counter[0] += 1  # composite ID
            for i in range(d.size):
                visit(d.element, path + [i])
        elif kind == 'struct':
            counter[0] += 1  # composite ID
            for (fname, ft) in d.fields:
                visit(ft, path + [fname])
        # void reserves nothing

    for (name, tname) in params:
        visit(tname, [name])
    if result is not None:
        visit(result[1], [result[0]])
    return slots, counter[0]


def recover(types, params, result, values):
    """Recover typed values from leaf integer values keyed by reserved ID.

    ``values`` maps reserved IDs to their little-endian decoded integers.
    Raises WireError on any leaf range violation.  Returns (inputs, model)
    where inputs is a parameter-name dict and model is the result value or
    None for a void result.
    """
    counter = [0]

    def take():
        v = values[counter[0]]
        counter[0] += 1
        return v

    def visit(tname):
        d = types.defs[tname]
        kind = d.kind
        if kind == 'alias':
            return visit(d.target)
        if kind == 'bool':
            v = take()
            if v not in (0, 1):
                raise WireError('bool out of range')
            return v == 1
        if kind == 'char':
            return chr(take())
        if kind == 'int':
            v = take()
            if v >= (1 << d.bits):
                raise WireError('int padding bits set')
            return v
        if kind == 'enum':
            v = take()
            if v >= len(d.values):
                raise WireError('enum index out of range')
            return d.values[v]
        if kind == 'string':
            counter[0] += 1  # buffer ID
            chars = []
            done = False
            for _ in range(d.maxsize):
                v = take()
                if not done:
                    if v == 0:
                        done = True
                    else:
                        chars.append(chr(v))
            return ''.join(chars)
        if kind == 'array':
            counter[0] += 1  # composite ID
            return [visit(d.element) for _ in range(d.size)]
        if kind == 'struct':
            counter[0] += 1  # composite ID
            return {fname: visit(ft) for (fname, ft) in d.fields}
        if kind == 'void':
            return None
        raise WireError('unknown kind')

    inputs = {}
    for (name, tname) in params:
        inputs[name] = visit(tname)
    model = None
    if result is not None:
        model = visit(result[1])
    return inputs, model
